    .map( { return ($0, Int.random(in: 0...100)) } )
    .print("Random")
    .multicast(subject: PassthroughSubject<(String, Int), Never>())

cancellable1 = pub
    .sink { print ("Stream 1 received: \($0)")}
cancellable2 = pub
